@scorer
def gold_first_line(outputs, expectations) -> bool:
    first = next((s.strip() for s in outputs["response"].splitlines() if s.strip()), "")
    first = re.sub(r"^answer\s*:\s*", "", first.replace("*", "").replace("`", ""), flags=re.I).strip().rstrip(".").lower()
    return first in [x.lower() for x in expectations["accepted_answers"]]

