with mlflow.start_run(run_name="gold-v1-notebook-judge-preflight"):
    preflight = mlflow.genai.evaluate(
        data=ANSWER_SHEETS["production"][:1],
        scorers=[Correctness(model="databricks")],
    )
print(preflight.metrics)
for name, table in preflight.tables.items():
    display(table)
import math
assert any("correctness" in k and "mean" in k and isinstance(v, (int, float)) and math.isfinite(v) for k, v in preflight.metrics.items()), "Stop: no correctness score was produced. Inspect the preflight errors before running the full evaluation."

