# COMMAND ----------
SCORERS = [
    Correctness(model="databricks"),
    Safety(model="databricks"),
    RelevanceToQuery(model="databricks"),
    Guidelines(name="conciseness", guidelines="The response states the requested value first, briefly justifies it with a source citation, and may include an informational-only disclaimer.", model="databricks"),
    gold_first_line,
]
EVALUATIONS = {}
for mode, rows in ANSWER_SHEETS.items():
    with mlflow.start_run(run_name=f"gold-v1-{mode}-notebook"):
        mlflow.set_tags({"benchmark":"mother-child-gold-v1", "prompt_mode":mode,
                         "evaluation_mode":"precomputed-answer-sheet", "clinical_certification":"false"})
        EVALUATIONS[mode] = mlflow.genai.evaluate(data=rows, scorers=SCORERS)
    print(mode, EVALUATIONS[mode].metrics)
    for name, table in EVALUATIONS[mode].tables.items():
        display(table)

